class Solution {
public:
    int totalHammingDistance(vector<int>& nums) {
        int total = 0, n = nums.size();
        for (int b = 0; b < 32; b++) {
            int ones = 0;
            for (int x : nums) {
                if ((x >> b) & 1) ones++;
            }
            total += ones * (n - ones);
        }
        return total;
    }
};

class Solution {
    public int totalHammingDistance(int[] nums) {
        int total = 0, n = nums.length;
        for (int b = 0; b < 32; b++) {
            int ones = 0;
            for (int x : nums) {
                if (((x >> b) & 1) == 1) ones++;
            }
            total += ones * (n - ones);
        }
        return total;
    }
}

var totalHammingDistance = function(nums) {
    let total = 0;
    const n = nums.length;
    for (let b = 0; b < 32; b++) {
        let ones = 0;
        for (const x of nums) {
            if ((x >> b) & 1) ones++;
        }
        total += ones * (n - ones);
    }
    return total;
};
